/**
 * opencode-control-surfbird-for-kitesurf：通过 Kitesurf CDP 协议控制浏览器引擎。
 *
 * OpenCode 插件（V2 Plugin API）。连接目标是任意 Kitesurf CDP 端点：
 * surfbird raw 镜像（:8787）、surfbird auth 镜像（:8080 + Bearer token）、
 * 上游 kitesurf（wrangler dev）。每个 OpenCode session 独占一条 WS 连接
 * = 一台独立浏览器；session.deleted 时断开，引擎侧该 session 的所有
 * tab 随之销毁。
 *
 * 工具前缀 surfbird_*：与 DSH 版一致，互不占位。
 * src/cdp/ 与 dsh-control-surfbird-for-kitesurf 共享（host 无关核心）。
 *
 * @module opencode-control-surfbird-for-kitesurf
 */
import { appendFileSync, mkdirSync } from 'node:fs';
import { homedir, tmpdir } from 'node:os';
import { join } from 'node:path';
import { Plugin } from '@opencode/plugin';
import { SessionRegistry } from "./cdp/session.js";
import { registerSurfbirdTools } from "./tools.js";
import { registerSurfbirdSkill } from "./skill.js";
import { resolveConfig } from "./config.js";
function envDebug(msg) {
    try {
        // 与 config-file.ts 的 configDirectory() 同款解析；内联而非 import——
        // config-file 依赖 devDep jsonc-parser，拉进来会让 server 入口运行时缺依赖。
        const dir = process.env.OPENCODE_CONFIG_DIR ??
            join(process.env.XDG_CONFIG_HOME ?? join(homedir(), '.config'), 'opencode');
        mkdirSync(dir, { recursive: true });
        appendFileSync(join(dir, 'surfbird-debug.log'), `${new Date().toISOString()} ${msg}\n`);
    }
    catch { /* debug log 尽力而为 */ }
}
export default Plugin.define({
    id: 'surfbird',
    async setup(ctx) {
        // options 每次调用重读：opencode.json 改动 + plugin reload 后生效
        const options = () => (ctx.options ?? {});
        const resolved = () => resolveConfig(options());
        const registry = new SessionRegistry({
            get maxSessions() { return resolved().maxSessions; },
            get idleEvictMs() { return resolved().idleEvictMs; },
        });
        const sessionOpts = () => {
            const c = resolved();
            return { endpoint: c.endpoint, token: c.token, requestTimeoutMs: c.requestTimeoutMs, keepaliveMs: c.keepaliveMs };
        };
        const disposeTools = await registerSurfbirdTools(ctx, {
            registry,
            sessionOpts,
            get requestTimeoutMs() { return resolved().requestTimeoutMs; },
            get outputDir() { return resolved().screenshotDir ?? join(tmpdir(), 'surfbird'); },
            configInfo: () => {
                const c = resolved();
                return { configSource: c.configSource, endpoint: c.endpoint, tokenSet: !!c.token, tokenFileError: c.tokenFileError, tokenFileEncrypted: c.tokenFileEncrypted };
            },
            onSessionError: (_key, err) => {
                if (resolved().debugLog)
                    envDebug(`session error: ${err instanceof Error ? err.message : String(err)}`);
            },
        });
        let disposeSkill;
        try {
            disposeSkill = await registerSurfbirdSkill(ctx);
        }
        catch { /* skill 注册失败不阻塞工具 */ }
        // session 删除 → 断开该 session 的浏览器（引擎侧 tab 全灭）
        const eventAbort = new AbortController();
        void (async () => {
            for await (const ev of ctx.event.subscribe({ types: ['session.deleted'], signal: eventAbort.signal })) {
                const sid = ev.data?.sessionID;
                if (typeof sid === 'string' && sid)
                    void registry.release(sid).catch(() => undefined);
            }
        })().catch(() => undefined);
        return async () => {
            eventAbort.abort();
            await disposeTools();
            await disposeSkill?.();
            await registry.disposeAll();
        };
    },
});

/**
 * opencode-control-surfbird-for-kitesurf：通过 Kitesurf CDP 协议控制浏览器引擎。
 *
 * OpenCode 插件（V2 Plugin API）。连接目标是任意 Kitesurf CDP 端点：
 * surfbird raw 镜像（:8787）、surfbird auth 镜像（:8080 + Bearer token）、
 * 上游 kitesurf（wrangler dev）。每个 OpenCode session 独占一条 WS 连接
 * = 一台独立浏览器；session.deleted 时断开，引擎侧该 session 的所有
 * tab 随之销毁。
 *
 * 工具前缀 surfbird_*：与 DSH 版一致，互不占位。
 * src/cdp/ 与 dsh-control-surfbird-for-kitesurf 共享（host 无关核心）。
 *
 * @module opencode-control-surfbird-for-kitesurf
 */

import { appendFileSync, mkdirSync } from 'node:fs'
import { homedir, tmpdir } from 'node:os'
import { join } from 'node:path'
import { Plugin } from '@opencode/plugin'
import { SessionRegistry } from './cdp/session.ts'
import type { SessionOptions } from './cdp/session.ts'
import { registerSurfbirdTools } from './tools.ts'
import { registerSurfbirdSkill } from './skill.ts'
import { resolveConfig, type ResolvedConfig } from './config.ts'

function envDebug(msg: string): void {
  try {
    // 与 config-file.ts 的 configDirectory() 同款解析；内联而非 import——
    // config-file 依赖 devDep jsonc-parser，拉进来会让 server 入口运行时缺依赖。
    const dir =
      process.env.OPENCODE_CONFIG_DIR ??
      join(process.env.XDG_CONFIG_HOME ?? join(homedir(), '.config'), 'opencode')
    mkdirSync(dir, { recursive: true })
    appendFileSync(join(dir, 'surfbird-debug.log'), `${new Date().toISOString()} ${msg}\n`)
  } catch { /* debug log 尽力而为 */ }
}

export default Plugin.define({
  id: 'surfbird',
  async setup(ctx) {
    // options 每次调用重读：opencode.json 改动 + plugin reload 后生效
    const options = (): Record<string, unknown> => (ctx.options ?? {}) as Record<string, unknown>
    const resolved = (): ResolvedConfig => resolveConfig(options())

    const registry = new SessionRegistry({
      get maxSessions() { return resolved().maxSessions },
      get idleEvictMs() { return resolved().idleEvictMs },
    })

    const sessionOpts = (): SessionOptions => {
      const c = resolved()
      return { endpoint: c.endpoint, token: c.token, requestTimeoutMs: c.requestTimeoutMs, keepaliveMs: c.keepaliveMs }
    }

    const disposeTools = await registerSurfbirdTools(ctx, {
      registry,
      sessionOpts,
      get requestTimeoutMs() { return resolved().requestTimeoutMs },
      get outputDir() { return resolved().screenshotDir ?? join(tmpdir(), 'surfbird') },
      configInfo: () => {
        const c = resolved()
        return { configSource: c.configSource, endpoint: c.endpoint, tokenSet: !!c.token, tokenFileError: c.tokenFileError, tokenFileEncrypted: c.tokenFileEncrypted }
      },
      onSessionError: (_key: string, err: unknown) => {
        if (resolved().debugLog) envDebug(`session error: ${err instanceof Error ? err.message : String(err)}`)
      },
    })

    let disposeSkill: (() => Promise<void>) | undefined
    try {
      disposeSkill = await registerSurfbirdSkill(ctx)
    } catch { /* skill 注册失败不阻塞工具 */ }

    // session 删除 → 断开该 session 的浏览器（引擎侧 tab 全灭）
    const eventAbort = new AbortController()
    void (async () => {
      for await (const ev of ctx.event.subscribe({ types: ['session.deleted'], signal: eventAbort.signal })) {
        const sid = (ev as { data?: { sessionID?: unknown } }).data?.sessionID
        if (typeof sid === 'string' && sid) void registry.release(sid).catch(() => undefined)
      }
    })().catch(() => undefined)

    return async () => {
      eventAbort.abort()
      await disposeTools()
      await disposeSkill?.()
      await registry.disposeAll()
    }
  },
})

/**
 * opencode-control-surfbird-for-kitesurf — GUI 插件的 main 进程入口。
 *
 * 桌面 main 进程持有 Node fs/net 权限；这里负责：
 * - 把设置页的 options 补丁写回 opencode.json(c)（jsonc 保注释 + tmp/rename 原子写，
 *   与 `opencode plugin add` 同款；config watcher 自动重载 server 与 GUI 插件）
 * - status：解析生效配置（含 tokenFile 解密）并探活引擎 /json/version
 * - importToken/importTokenFile：token 明文或 surfbird-v1: 密文 → 加密落盘 tokenFile
 *
 * 文件读写逻辑在 src/config-file.ts / src/token-store.ts，与 TUI 设置页共用。
 */
import type { Plugin } from '@opencode/plugin/gui'
import { readFile } from 'node:fs/promises'
import path from 'node:path'
import { ConfigIpc } from './contract.ts'
import { configDirectory, findPluginConfig, writePluginOptions } from '../config-file.ts'
import { endpointHttpBase, resolveConfig } from '../config.ts'
import { storeToken } from '../token-store.ts'

function str(v: unknown): string | undefined {
  return typeof v === 'string' && v.trim() ? v.trim() : undefined
}

/** tokenFile 缺省路径：~/.config/opencode/surfbird-token。 */
function defaultTokenFile(): string {
  return path.join(configDirectory(), 'surfbird-token')
}

/** IPC setOptions 允许写回的 options 键——与 src/config.ts 的 ResolvedConfig 字段一一对应。 */
const OPTION_KEYS = new Set([
  'endpoint',
  'token',
  'tokenFile',
  'requestTimeoutMs',
  'keepaliveMs',
  'maxSessions',
  'idleEvictMs',
  'screenshotDir',
  'debugLog',
])

const main: Plugin.MainSetup = (ctx) => {
  ctx.provide(ConfigIpc, {
    configPath: async () => (await findPluginConfig()).file,
    getOptions: async () => (await findPluginConfig()).options,
    setOptions: async (patch) => {
      for (const key of Object.keys(patch)) {
        if (!OPTION_KEYS.has(key)) throw new Error(`unknown option key: ${key}`)
      }
      const loc = await findPluginConfig()
      await writePluginOptions(loc.file, patch)
      ctx.log.write('info', 'surfbird options updated', { file: loc.file })
    },
    status: async () => {
      const c = resolveConfig((await findPluginConfig()).options)
      const out = {
        configSource: c.configSource,
        endpoint: c.endpoint,
        tokenSet: !!c.token,
        tokenFile: c.tokenFile ?? '',
        tokenFileEncrypted: c.tokenFileEncrypted === true,
        tokenFileError: c.tokenFileError ?? '',
        reachable: false,
        product: '',
        protocolVersion: '',
        probeStatus: 0,
        probeError: '',
      }
      const base = endpointHttpBase(c.endpoint)
      if (!base) {
        out.probeError = 'endpoint is not a valid URL'
        return out
      }
      const ctrl = new AbortController()
      const timer = setTimeout(() => ctrl.abort(), 5000)
      try {
        const headers: Record<string, string> = {}
        if (c.token) headers.authorization = `Bearer ${c.token}`
        const res = await fetch(`${base}/json/version`, { signal: ctrl.signal, headers })
        out.probeStatus = res.status
        if (res.ok) {
          const v = (await res.json()) as Record<string, unknown>
          out.reachable = true
          out.product = String(v.Browser ?? v.product ?? '')
          out.protocolVersion = String(v['Protocol-Version'] ?? v.protocolVersion ?? '')
        } else {
          out.probeError = `HTTP ${res.status}`
        }
      } catch (e) {
        out.probeError = e instanceof Error ? e.message : String(e)
      } finally {
        clearTimeout(timer)
      }
      return out
    },
    importToken: async ({ value }) => {
      const options = (await findPluginConfig()).options
      const target = str(options.tokenFile) ?? defaultTokenFile()
      return storeToken(value, target)
    },
    importTokenFile: async ({ path: file }) => {
      const options = (await findPluginConfig()).options
      const target = str(options.tokenFile) ?? defaultTokenFile()
      let content: string
      try {
        content = await readFile(file, 'utf8')
      } catch (e) {
        throw new Error(`cannot read file: ${e instanceof Error ? e.message : String(e)}`)
      }
      return storeToken(content, target)
    },
  })
}

export default main
